import com.project.system.service.*;import java.math.BigDecimal;import java.util.*;import org.springframework.context.annotation.*;import org.springframework.jdbc.core.JdbcTemplate;
public class MerchantConsumptionIntegration{
 @Configuration @Import(MerchantIntegration.Config.class) static class Config{@Bean public MerchantConsumptionService consumption(){return new MerchantConsumptionService();}}
 static int n;static void check(boolean b,String name){if(!b)throw new AssertionError(name);n++;System.out.println("PASS "+name);}static void reject(Runnable r,String name){try{r.run();}catch(IllegalArgumentException e){check(true,name);return;}throw new AssertionError(name);}
 public static void main(String[]args){try(AnnotationConfigApplicationContext c=new AnnotationConfigApplicationContext(Config.class)){MerchantConsumptionService s=c.getBean(MerchantConsumptionService.class);MerchantService m=c.getBean(MerchantService.class);WalletService w=c.getBean(WalletService.class);JdbcTemplate db=c.getBean(JdbcTemplate.class);w.status(2,"ACTIVE");w.trade(2,"RECHARGE",new BigDecimal("20"),null,null,UUID.randomUUID().toString(),1);long merchant=m.save(null,"消费视角测试","CATERING","测试","13800000003","测试地址","",1);String key=UUID.randomUUID().toString();Map<String,Object> receipt=s.consume(merchant,"S002",new BigDecimal("5"),key,1);check(receipt.equals(s.consume(merchant,"S002",new BigDecimal("5"),key,1)),"consumption duplicate does not debit twice");long pay=((Number)receipt.get("id")).longValue();w.trade(2,"REFUND",BigDecimal.ONE,null,pay,UUID.randomUUID().toString(),1);String phone=db.queryForObject("select phonenumber from sys_user where user_id=2",String.class);Map<String,Object> q=s.query(merchant,"S002",phone,null,null,1);check(((Number)q.get("total")).intValue()==2,"merchant student phone filters include payment and refund");for(String p:Arrays.asList("day","month","year")){Map<?,?> sums=(Map<?,?>)q.get(p);check(((BigDecimal)sums.get("income")).compareTo(new BigDecimal("5"))==0&&((BigDecimal)sums.get("refunds")).compareTo(BigDecimal.ONE)==0&&((BigDecimal)sums.get("net")).compareTo(new BigDecimal("4"))==0,p+" revenue includes refund deduction");}check(((Number)s.query(merchant,null,"000",null,null,1).get("total")).intValue()==0,"phone filter excludes mismatched people");check(((Number)s.query(merchant,null,null,"2000-01-01","2000-01-02",1).get("total")).intValue()==0,"time range filters ledger");w.status(2,"LOST");reject(()->s.consume(merchant,"S002",BigDecimal.ONE,UUID.randomUUID().toString(),1),"lost wallet rejected");w.status(2,"ACTIVE");m.status(merchant,0,"测试停用",1);reject(()->s.consume(merchant,"S002",BigDecimal.ONE,UUID.randomUUID().toString(),1),"disabled merchant rejected");reject(()->s.consume(3,"S002",BigDecimal.ONE,UUID.randomUUID().toString(),1),"system debit merchant excluded");reject(()->s.query(merchant,null,null,"2027-01-01","2026-01-01",1),"reversed dates rejected");System.out.println("PASS TOTAL "+n);}}
}
